#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void conv2d_kernel(
    const half* input,
    const half* weight,
    half* output,
    int batch_size,
    int channels,
    int height,
    int width,
    int out_channels,
    int kernel_h,
    int kernel_w,
    int stride_h,
    int stride_w,
    int pad_h,
    int pad_w,
    int out_h,
    int out_w
) {
    int batch_idx = blockIdx.x;
    int channel_idx = blockIdx.y;
    int out_y = blockIdx.z * blockDim.x + threadIdx.x;
    int out_x = threadIdx.y;

    if (out_y >= out_h || out_x >= out_w || batch_idx >= batch_size || channel_idx >= out_channels) {
        return;
    }

    // Initialize accumulator with zero
    float sum = 0.0f;

    // Perform convolution
    for (int c = 0; c < channels; ++c) {
        for (int ky = 0; ky < kernel_h; ++ky) {
            for (int kx = 0; kx < kernel_w; ++kx) {
                int input_y = out_y * stride_h - pad_h + ky;
                int input_x = out_x * stride_w - pad_w + kx;

                // Check bounds
                if (input_y >= 0 && input_y < height && input_x >= 0 && input_x < width) {
                    int input_idx = batch_idx * (channels * height * width) +
                                   c * (height * width) +
                                   input_y * width +
                                   input_x;

                    int weight_idx = channel_idx * (channels * kernel_h * kernel_w) +
                                    c * (kernel_h * kernel_w) +
                                    ky * kernel_w +
                                    kx;

                    sum += static_cast<float>(input[input_idx]) * static_cast<float>(weight[weight_idx]);
                }
            }
        }
    }

    // Store result
    int output_idx = batch_idx * (out_channels * out_h * out_w) +
                     channel_idx * (out_h * out_w) +
                     out_y * out_w +
                     out_x;

    output[output_idx] = __float2half(sum);
}

// Host wrapper function
extern "C" void launch_conv2d(
    const half* input,
    const half* weight,
    half* output,
    int batch_size,
    int channels,
    int height,
    int width,
    int out_channels,
    int kernel_h,
    int kernel_w,
    int stride_h,
    int stride_w,
    int pad_h,
    int pad_w,
    int out_h,
    int out_w
) {
    dim3 grid_dim(batch_size, out_channels, (out_h + 15) / 16);
    dim3 block_dim(16, 16);

    conv2d_kernel<<<grid_dim, block_dim>>>(
        input, weight, output,
        batch_size, channels, height, width,
        out_channels, kernel_h, kernel_w,
        stride_h, stride_w, pad_h, pad_w,
        out_h, out_w
    );

    cudaDeviceSynchronize();
}
"""

# Python model definition
class ModelNew(torch.nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.conv1 = torch.nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)

        # Load CUDA extension
        self.conv2d_kernel = load_inline(
            name="conv2d_kernel",
            cpp_sources="",
            cuda_sources=cuda_source,
            functions=["launch_conv2d"],
            verbose=False
        )

    def forward(self, x):
        # Get dimensions
        batch_size, channels, height, width = x.shape

        # Get weight and bias from conv1 layer
        weight = self.conv1.weight.data.contiguous().to(torch.float16)
        bias = self.conv1.bias.data.contiguous().to(torch.float16) if self.conv1.bias is not None else None

        # Convolution parameters
        out_channels = self.conv1.out_channels
        kernel_h, kernel_w = self.conv1.kernel_size
        stride_h, stride_w = self.conv1.stride
        pad_h, pad_w = self.conv1.padding
        out_h = (height + 2 * pad_h - kernel_h) // stride_h + 1
        out_w = (width + 2 * pad_w - kernel_w) // stride_w + 1

        # Create output tensor
        output = torch.empty(batch_size, out_channels, out_h, out_w, dtype=torch.float16, device=x.device)

        # Launch CUDA kernel
        self.conv2d_kernel.launch_conv2d(
            x.contiguous().view(-1).data_ptr(),
            weight.contiguous().view(-1).data_ptr(),
            output.view(-1).data_ptr(),
            batch_size,
            channels,
            height,
            width,
            out_channels,
            kernel_h,
            kernel_w,
            stride_h,
            stride_w,
            pad_h,
            pad_w,
            out_h,
            out_w
        )

        # Add bias if present
        if bias is not None:
            output = output + bias.view(1, -1, 1, 1)

        return output

